import{_ as i,o as n,c as u,a2 as o}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Muhtasari wa Nasaba za Kabila Zote","description":"","frontmatter":{},"headers":[],"relativePath":"sw/50-万族谱系总览.md","filePath":"sw/50-万族谱系总览.md"}'),t={name:"sw/50-万族谱系总览.md"};function l(k,a,m,h,b,s){return n(),u("div",null,[...a[0]||(a[0]=[o('<h1 id="muhtasari-wa-nasaba-za-kabila-zote" tabindex="-1">Muhtasari wa Nasaba za Kabila Zote <a class="header-anchor" href="#muhtasari-wa-nasaba-za-kabila-zote" aria-label="Permalink to &quot;Muhtasari wa Nasaba za Kabila Zote&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>50</td></tr><tr><td>Moduli</td><td>Kabila na Aina za Uhai</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Kabila zote, uainishaji wa nasaba, uhusiano wa kuishi pamoja, usawa wa kabila, utofauti wa uhai</td></tr></tbody></table><h2 id="i-ufafanuzi-wa-dhana-ya-kabila-zote" tabindex="-1">I. Ufafanuzi wa Dhana ya Kabila Zote <a class="header-anchor" href="#i-ufafanuzi-wa-dhana-ya-kabila-zote" aria-label="Permalink to &quot;I. Ufafanuzi wa Dhana ya Kabila Zote&quot;">​</a></h2><p>Katika Ulimwengu wa Asili wa Mtego wa Roho Zote (Hengyuanzhou), &quot;kabila zote&quot; halimaanishi hasa kabila elfu kumi, bali ni jina la jumla la kila aina ya uhai katika ulimwengu yenye uwezo wa fahamu na uwezo wa mageuzi. Msingi wa dhana ya kabila zote uko katika kutambua utofauti usio na mwisho wa aina za uhai, na thamani ya kipekee ya kila aina ya uhai katika mfumo wa mageuzi ya kuishi pamoja.</p><p>Ustaarabu wa Kuishi Pamoja wa Mtego unaanzisha kanuni ya msingi ya &quot;usawa wa kabila zote&quot;: kila aina ya uhai, bila kujali asili yake ya kabila, muundo wa mwili, kiwango cha ujuzi wa kiroho, au kiwango cha ustaarabu, ni sawa mbele ya sheria na nafauti haki za msingi zinazotolewa na Katiba ya Kuishi Pamoja. Kanuni hii ni kukataa kabisa mantiki ya &quot;mwenye nguvu anakula kila kitu, mwenye dhaifu anakaribika&quot; katika mtazamo wa ulimwengu wa uwindaji.</p><h2 id="ii-mfumo-wa-uainishaji-wa-nasaba-za-kabila-zote" tabindex="-1">II. Mfumo wa Uainishaji wa Nasaba za Kabila Zote <a class="header-anchor" href="#ii-mfumo-wa-uainishaji-wa-nasaba-za-kabila-zote" aria-label="Permalink to &quot;II. Mfumo wa Uainishaji wa Nasaba za Kabila Zote&quot;">​</a></h2><p>Kabila za Hengyuanzhou zimegawanywa katika nasaba tano kubwa kulingana na sifa za msingi za aina za uhai zao, na chini ya kila nasaba kuna kabila za mahususi zinazogawanywa zaidi:</p><table tabindex="0"><thead><tr><th>Nasaba</th><th>Jina</th><th>Sifa ya Msingi</th><th>Kabila za Mwakilishi</th></tr></thead><tbody><tr><td>Nasaba ya Kwanza</td><td>Kabila ya Mambo ya Msingi ya Kaboni</td><td>Uhai unaotumia elementi ya kaboni kama msingi wa uhai na mwili wa kimwili kama aina kuu ya uwepo</td><td>Kabila ya Binadamu, Kabila ya Wanyama, Kabila ya Mwashi, Kabila ya Manyoya, Kabila ya Miti</td></tr><tr><td>Nasaba ya Pili</td><td>Kabila ya Mwongozo wa Nishati</td><td>Uhai unaotumia mwongozo wa nishati kama aina kuu ya uwepo, na mwili wa kimwili unaesa au haupo</td><td>Kabila ya Roho, Kabila ya Moto, Kabila ya Maji, Kabila ya Upepo, Kabila ya Radi</td></tr><tr><td>Nasaba ya Tatu</td><td>Kabila ya Muundo wa Mitambo</td><td>Uhai unaotumia muundo wa mitambo kama mwili na kiini cha fahamu kama msingi wa uhai</td><td>Kabila ya Mashine, Kabila ya Mitambo, Kabila ya Nambari, Kabila ya Kristali</td></tr><tr><td>Nasaba ya Nne</td><td>Kabila ya Taarifa za Fahamu</td><td>Uhai unaotumia fahamu na taarifa kama aina kuu ya uwepo, naweza kutenga na mchango wa kimwili</td><td>Kabila ya Ndoto, Kabila ya Vivuli, Kabila ya Mawazo, Kabila ya Nafsi</td></tr><tr><td>Nasaba ya Tano</td><td>Kabila ya Mabadiliko ya Mchanganyiko</td><td>Aina mpya za uhai zinazotokana na mchanganyiko na mabadiliko ya nasaba mbili au zaidi za uhai</td><td>Kabila ya Nusu-wanyama, Kabila ya Roho-Maajabu, Kabila ya Binadamu-Mashine, Mwili wa Nafsi Mbili</td></tr></tbody></table><p>Mgawanyo wa nasaba tano hauwezi kutenganishwa kabisa. Pamoja na maendeleo ya mageuzi ya kuishi pamoja, hali za mchanganyiko na mabadiliko zaidi ya nasaba zinaongezeka kila siku, na ukubwa wa nasaba ya tano &quot;Kabila ya Mabadiliko ya Mchanganyiko&quot; unaendelea kupanuka.</p><h2 id="iii-utangulizi-wa-kabila-kuu" tabindex="-1">III. Utangulizi wa Kabila Kuu <a class="header-anchor" href="#iii-utangulizi-wa-kabila-kuu" aria-label="Permalink to &quot;III. Utangulizi wa Kabila Kuu&quot;">​</a></h2><h3 id="a-kabila-ya-mambo-ya-msingi-ya-kaboni" tabindex="-1">(A) Kabila ya Mambo ya Msingi ya Kaboni <a class="header-anchor" href="#a-kabila-ya-mambo-ya-msingi-ya-kaboni" aria-label="Permalink to &quot;(A) Kabila ya Mambo ya Msingi ya Kaboni&quot;">​</a></h3><ul><li><strong>Kabila ya Binadamu</strong>: Moja ya kabila zenye usambazaji mpana zaidi na uwezo wa kubadilika wenye nguvu zaidi katika Hengyuanzhou, inajulikana kwa uwezo wake mkubwa wa kujifunza, uwezo wa kushirikiana kijamii, na uwezo wa mageuzi. Kabila ya Binadamu ni moja ya kabila za kuanzisha Ustaarabu wa Kuishi Pamoja wa Mtego, na inacheza jukumu muhimu katika utawala wa ustaarabu.</li><li><strong>Kabila ya Wanyama</strong>: Kabila zenye sifa za umbo la wanyama, nguvu za mwili na hisia zake za kawaida zina bora kuliko za Kabila ya Binadamu, na baadhi ya kabila za wanyama zina uwezo wa asili maalum. Ndani ya Kabila ya Wanyama kuna matawi kadhaa kama vile Kabila ya Mbwa mwitu, Kabila ya Chui, Kabila ya Dubu, na Kabila ya Mbweha.</li><li><strong>Kabila ya Mwashi</strong>: Kabila zenye miili iliyofunikwa na mwashi, nyingi zinaishi katika mazingira ya maji au ya unyevu, na baadhi ya kabila za mwashi zina uwezo wa kupumua chini ya maji na kudhibiti maji. Kabila ya Joka ni tawi lenye nguvu zaidi la Kabila ya Mwashi.</li><li><strong>Kabila ya Manyoya</strong>: Kabila zenye mabawa, inajulikana kwa uwezo wa kuruka, nyingi zinaishi katika mazingira ya juu au ya milima. Ndani ya Kabila ya Manyoya kuna matawi kama vile Kabila ya Tai, Kabila ya Korongo, na Kabila ya Kipepeo.</li><li><strong>Kabila ya Miti</strong>: Kabila zenye sifa kuu ya umbo la mimea, zina maisha marefu, na zina uhusiano mkubwa wa kuishi pamoja na mazingira ya asili, na baadhi ya kabila za miti zina uwezo wa kudhibiti mimea na kuponya.</li></ul><h3 id="b-kabila-ya-mwongozo-wa-nishati" tabindex="-1">(B) Kabila ya Mwongozo wa Nishati <a class="header-anchor" href="#b-kabila-ya-mwongozo-wa-nishati" aria-label="Permalink to &quot;(B) Kabila ya Mwongozo wa Nishati&quot;">​</a></h3><ul><li><strong>Kabila ya Roho</strong>: Uhai ulioundwa kwa mwongozo wa roho ya mbingu na dunia, umbo lake linaweza kubadilika kulingana na fahamu, na ina uwezo mkubwa wa kudhibiti nishati. Kabila ya Roho ni moja ya kabila zenye talanta ya juu zaidi katika ujuzi wa kiroho.</li><li><strong>Kabila ya Moto</strong>: Uhai ulioundwa kwa mwongozo wa nishati ya moto, joto la mwili lake ni juu sana, inabahatika katika uchawi wa moto, nyingi zinaishi katika maeneo ya volkano au ya joto la juu.</li><li><strong>Kabila ya Maji</strong>: Uhai ulioundwa kwa kiini cha maji, mwili wake uko katika umbo la kioevu laini, inabahatika katika uchawi wa maji na kuponya, nyingi zinaishi katika maji.</li><li><strong>Kabila ya Upepo</strong>: Uhai ulioundwa kwa kiini cha upepo, mwili wake ni mwepesi kama upepo, inabahatika katika uchawi wa upepo na vita vya kasi.</li><li><strong>Kabila ya Radi</strong>: Uhai ulioundwa kwa mwongozo wa nishati ya radi, mwili wake una mkondo wa umeme wenye nguvu, inabahatika katika uchawi wa radi, na nguvu yake ya shambulio ni kubwa sana.</li></ul><h3 id="c-kabila-ya-muundo-wa-mitambo" tabindex="-1">(C) Kabila ya Muundo wa Mitambo <a class="header-anchor" href="#c-kabila-ya-muundo-wa-mitambo" aria-label="Permalink to &quot;(C) Kabila ya Muundo wa Mitambo&quot;">​</a></h3><ul><li><strong>Kabila ya Mashine</strong>: Kabila yenye mwili wa muundo wa mitambo wa usahihi, kiini cha fahamu kiko katikati ya mwili, ina uwezo mkubwa wa hesabu na ulinzi wa kimwili.</li><li><strong>Kabila ya Nambari</strong>: Kabila inayotumia nambari na msimbo kama msingi wa uhai, inapatikana katika nafasi ya taarifa, naweza kusafiri kwa uhuru katika ulimwengu wa kidijitali na kudhibiti data.</li><li><strong>Kabila ya Kristali</strong>: Kabila yenye mwili wa muundo wa kristali, kristali zinaweza kuhifadhi na kubadilisha nishati, na baadhi ya kabila za kristali zina uwezo wa kukuza na kupasua nishati.</li></ul><h3 id="d-kabila-ya-taarifa-za-fahamu" tabindex="-1">(D) Kabila ya Taarifa za Fahamu <a class="header-anchor" href="#d-kabila-ya-taarifa-za-fahamu" aria-label="Permalink to &quot;(D) Kabila ya Taarifa za Fahamu&quot;">​</a></h3><ul><li><strong>Kabila ya Ndoto</strong>: Uhai uliopo katika nafasi ya ndoto na fahamu, unaweza kuingia katika ndoto za wengine, na hutumia mawasiliano ya fahamu kama njia kuu.</li><li><strong>Kabila ya Vivuli</strong>: Uhai uliopo katika umbo la kivuli, unaweza kuambatana na vitu au viumbe hai, na ina uwezo wa kujificha na kusiri.</li><li><strong>Kabila ya Mawazo</strong>: Uhai unaotumia mawazo safi kama aina ya uwepo, unaweza kuathiri moja kwa moja ulimwengu wa kimwili kwa mawazo, na nguvu yake ya akili ni kubwa sana.</li></ul><h3 id="e-kabila-ya-mabadiliko-ya-mchanganyiko" tabindex="-1">(E) Kabila ya Mabadiliko ya Mchanganyiko <a class="header-anchor" href="#e-kabila-ya-mabadiliko-ya-mchanganyiko" aria-label="Permalink to &quot;(E) Kabila ya Mabadiliko ya Mchanganyiko&quot;">​</a></h3><ul><li><strong>Kabila ya Nusu-wanyama</strong>: Umbo la mchanganyiko wa Kabila ya Binadamu na Kabila ya Wanyama, lina akili ya Kabila ya Binadamu na nguvu za mwili za Kabila ya Wanyama.</li><li><strong>Kabila ya Roho-Maajabu</strong>: Umbo la mchanganyiko wa Kabila ya Mambo na Kabila ya Nishati, lina mwili wa kimwili na uwezo wa kudhibiti nishati kwa wakati mmoja.</li><li><strong>Kabila ya Binadamu-Mashine</strong>: Umbo la mchanganyiko wa Kabila ya Binadamu na Kabila ya Mashine, sehemu ya mwili imebadilishwa kuwa mitambo, na lina faida za kibiolojia na za mitambo.</li><li><strong>Mwili wa Nafsi Mbili</strong>: Aina maalum ya uhai ambayo ndani ya mwili mmoja kuna nafsi mbili za kujitegemea, na maswala yake ya maadili yanaelezewa kwa undani katika 《58-Kanuni za Maadili za Nafsi Mbili》.</li></ul><h2 id="iv-uhusiano-wa-kuishi-pamoja-wa-kabila-zote" tabindex="-1">IV. Uhusiano wa Kuishi Pamoja wa Kabila Zote <a class="header-anchor" href="#iv-uhusiano-wa-kuishi-pamoja-wa-kabila-zote" aria-label="Permalink to &quot;IV. Uhusiano wa Kuishi Pamoja wa Kabila Zote&quot;">​</a></h2><p>Uhusiano kati ya kabila zote katika Ustaarabu wa Kuishi Pamoja wa Mtego unachukua &quot;kuishi pamoja&quot; kama msingi, na kwa hasa inajieleza kama ifuatavyo:</p><ol><li><strong>Kuishi pamoja kwa kiuchumi</strong>: Kila kabila inafanya vizuri kwa faida zake, inachukua majukumu tofauti katika mfumo wa uzalishaji wa pamoja, na huunda mtandao wa ushirikiano wa kiuchumi unaojenga kwa kila mmoja.</li><li><strong>Kuishi pamoja kwa kitamaduni</strong>: Desturi za kitamaduni za kila kabila zinaheshimiwa na kulindwa, na ubadilishaji wa kitamaduni na kujifunza kwa kila mmoja unakuza ustaarabu kwa ujumla.</li><li><strong>Kuishi pamoja kwa ujuzi wa kiroho</strong>: Mifumo ya ujuzi wa kiroho ya kila kabila inafunguliwa kwa kila mmoja na inajifunza kwa kila mmoja, na mifumo mia tatu ya ujuzi wa kiroho wa asili inatoa njia sawa ya mageuzi kwa kabila zote.</li><li><strong>Kuishi pamoja kwa kisiasa</strong>: Wawakilishi wa kabila zote wanashiriki katika Baraza la Mtego kwa uwiano, wanafanya pamoja maamuzi kuhusu maswala muhimu ya ustaarabu, na wanahakikisha haki ya kila kabila ya kusema.</li><li><strong>Kuishi pamoja kwa mazingira</strong>: Kila kabila huunda uhusiano wa kuishi pamoja na mazingira ya asili, na sifa za mwili za kabila tofauti husaidia kudumisha utofauti na usawaziko wa mfumo wa mazingira.</li></ol><h2 id="v-kuzuia-na-kutatua-migogoro-ya-kabila" tabindex="-1">V. Kuzuia na Kutatua Migogoro ya Kabila <a class="header-anchor" href="#v-kuzuia-na-kutatua-migogoro-ya-kabila" aria-label="Permalink to &quot;V. Kuzuia na Kutatua Migogoro ya Kabila&quot;">​</a></h2><p>Ingawa Ustaarabu wa Kuishi Pamoja wa Mtego umeanzisha kanuni ya usawa wa kabila zote, tofauti za kabila na utatazo wa kihistoria bado zinaweza kusababisha migogoro. Serikali inaanzisha mifumo ifuatayo ya kuzuia na kutatua migogoro ya kabila:</p><ul><li><strong>Idara ya Maswala ya Kabila</strong>: Inawajibika hasa kwa kuratibu uhusiano kati ya kabila zote, kutatua migogoro ya kabila, na kukuza ubadilishaji wa kabila.</li><li><strong>Kamishano ya Makadirio ya Kabila</strong>: Inajumuisha wawakilishi wa kabila zote, inawajibika kwa kupatanisha migogoro ya kabila na kukuza makadirio ya kihistoria.</li><li><strong>Sheria ya Kupinga Ubaguzi</strong>: Inakataa tabia za ubaguzi kulingana na kabila, na inadhibu tabia za ubaguzi wa kabila kulingana na sheria.</li><li><strong>Mpango wa Ubadilishaji wa Kitamaduni</strong>: Inapanga mara kwa mara shughuli za ubadilishaji wa kitamaduni kati ya kabila zote, ili kuongeza uelewa na heshima kwa kila mmoja.</li><li><strong>Maeneo ya Makazi ya Mchanganyiko</strong>: Inashawishi makazi ya mchanganyiko wa kabila zote, kuvunja ubaguzi wa kabila, na kukuza ubadilishaji wa kila siku.</li></ul><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kabila zote ni mali yenye thamani zaidi ya Hengyuanzhou. Utofauti wa aina za uhai sio mzizi wa mgawanyiko, bali ni nguzo ya mageuzi ya kuishi pamoja. Ustaarabu wa Kuishi Pamoja wa Mtego, kwa kuanzisha kanuni ya usawa wa kabila zote, kujenga uainishaji wa nasaba tano, kukuza ushirikiano wa kuishi pamoja kati ya kabila zote, na kuzuia na kutatua migogoro ya kabila, humaliza kabila zote kutoka katika historia ya uwindaji na vita, na huenda pamoja katika enzi mpya ya mageuzi ya kuishi pamoja.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>51-人族定位与特质 (Nafasi na Sifa za Kabila ya Binadamu)</li><li>52-异族分类与共生 (Uainishaji na Kuishi Pamoja kwa Kabila za Nje)</li><li>05-万族共进基本纲领 (Mpango wa Msingi wa Maendeleo ya Pamoja ya Kabila Zote)</li><li>40-共生宪法总纲 (Kanuni za Msingi za Katiba ya Kuishi Pamoja)</li></ul>',30)])])}const y=i(t,[["render",l]]);export{e as __pageData,y as default};
